1	/**
2	 * The MHPCO price list: what each insured thing costs before any modifier.
3	 *
4	 * This module owns catalogue knowledge only — which item types the office
5	 * recognises and the base premium it charges for them. It deliberately knows
6	 * nothing about surcharges, discounts, the processing fee or rounding: those
7	 * are underwriting policy and change for entirely different reasons. The
8	 * building-block discount for alike components is likewise not here; this
9	 * module only supplies the per-component rate the block rule prices against.
10	 */
11	
12	import { type Item } from "./item.js";
13	import { componentsBasePremium } from "./component-blocks.js";
14	
15	/** The MHPCO price list for main items: base premium in G per item type. */
16	const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	};
22	
23	/**
24	 * Components — runes, moonstones and their kin — are not listed individually on
25	 * the main price list. MHPCO charges one uniform rate per component.
26	 */
27	const COMPONENT_BASE_PREMIUM_G = 25;
28	
29	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
30	
31	function isComponent(item: Item): boolean {
32	  return COMPONENT_TYPES.includes(item.type);
33	}
34	
35	/**
36	 * The base premium of a single item, as the item-specific risk surcharges see
37	 * it: the price list rate for the item on its own, before any building-block
38	 * discount the policy as a whole may earn.
39	 */
40	export function itemBasePremium(item: Item): number {
41	  return isComponent(item) ? COMPONENT_BASE_PREMIUM_G : mainItemBasePremium(item);
42	}
43	
44	/**
45	 * The base premium of a single main item according to the MHPCO price list.
46	 *
47	 * The office insures only what its price list names. An item of any other kind
48	 * is not something MHPCO covers, so it is refused rather than priced.
49	 */
50	function mainItemBasePremium(item: Item): number {
51	  const basePremium = MAIN_ITEM_BASE_PREMIUM_G[item.type];
52	  if (basePremium === undefined) {
53	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
54	  }
55	  return basePremium;
56	}
57	
58	/**
59	 * The sum of the base premiums of all insured items, before any modifier.
60	 *
61	 * Main items are priced one by one straight off the price list; components are
62	 * handed to the building-block rule as a group, because their price depends on
63	 * how many alike ones the policy covers.
64	 */
65	export function policyBasePremium(items: readonly Item[]): number {
66	  const mainItemsTotal = items
67	    .filter((item) => !isComponent(item))
68	    .reduce((sum, item) => sum + mainItemBasePremium(item), 0);
69	  return (
70	    mainItemsTotal + componentsBasePremium(items.filter(isComponent), COMPONENT_BASE_PREMIUM_G)
71	  );
72	}
