1	import { policyBasePremium } from "./price-list.js";
2	import { type Item } from "./item.js";
3	import { itemRiskSurcharges } from "./item-risk.js";
4	import { policyModifiers } from "./customer-standing.js";
5	import { type Customer } from "./customer.js";
6	import { roundPremiumInMHPCOFavour } from "./mhpco-rounding.js";
7	
8	export type { Item, Customer };
9	
10	/** MHPCO adds a flat processing fee to every premium, at the very end. */
11	const PROCESSING_FEE_G = 5;
12	
13	/**
14	 * Assembles the bill in the order the office bills it: the price-list base
15	 * premium of the policy, the risk surcharges its individual items carry, the
16	 * modifiers rated on the policy as a whole, and finally the processing fee.
17	 *
18	 * Each of those amounts is ruled on elsewhere; this function only knows the
19	 * order they are applied in and that the total is rounded once, at the end.
20	 */
21	export function quote(customer: Customer, items: readonly Item[]): number {
22	  const policyBase = policyBasePremium(items);
23	  const premium =
24	    policyBase +
25	    itemRiskSurcharges(items) +
26	    policyModifiers(customer, policyBase) +
27	    PROCESSING_FEE_G;
28	  return roundPremiumInMHPCOFavour(premium);
29	}
