/**
 * The base premium of a single main item according to the MHPCO price list.
 *
 * The office insures only what its price list names, so an item absent from the
 * catalogue is one MHPCO does not cover: it is refused rather than priced. The
 * lookup and the coverage ruling are deliberately the same step — the missing
 * entry *is* the refusal, and splitting them would let the two drift apart.
 */
function mainItemBasePremium(item: Item): number {
  const basePremium = MAIN_ITEM_BASE_PREMIUM_G[item.type];
  if (basePremium === undefined) {
    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
  }
  return basePremium;
}
